function fmt(n){return Math.floor(n||0).toLocaleString('en-US')}function clamp(n,a,b){return Math.max(a,Math.min(b,n))}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
