function rarityRoll(){const ev=activeEvent();const luck=(1+Math.max(0,S.upgrades.luck-1)*.075+gearBonus('luck')+(S.endless.equipped?.1:0))*globalBoost()*(ev.active&&ev.type==='luck'?2:1);const weights=RARITIES.map((r,i)=>{if(i===0)return r[1]/luck;return r[1]*Math.pow(luck,Math.min(i,5)*.55)});const total=weights.reduce((a,b)=>a+b,0);let roll=Math.random()*total;for(let i=0;i<weights.length;i++){roll-=weights[i];if(roll<=0)return RARITIES[i][0]}return 'Common';}
function raceRoll(){const bonus=Math.max(0,S.upgrades.race-1)*.12;const weights=RACE_ODDS.map((r,i)=>i===0?r[1]:r[1]*(1+bonus*i*1.5));const total=weights.reduce((a,b)=>a+b,0);let x=Math.random()*total;for(const r of RACE_ODDS){let w=weights[RACE_ODDS.indexOf(r)];x-=w;if(x<=0)return {name:r[0],mult:r[2]}}return {name:'Human',mult:1};}
function makeUnit(){const rarity=rarityRoll(),race=raceRoll(),n=S.nextUnitId,idx=hash(`${n}-${Math.random()}-${Date.now()}`),species=SPECIES[idx%SPECIES.length],prefix=PREFIXES[(idx>>>4)%PREFIXES.length],element=ELEMENTS[(idx>>>8)%ELEMENTS.length];S.summonsMade++;const existing=S.units.find(u=>u.species===species&&u.race===race.name);if(existing){const tier=RARITIES.findIndex(r=>r[0]===rarity);const shards=Math.max(1,Math.floor((tier+1)*(race.name==='Demonic'?3:1)));S.shards+=shards;const convertedGold=Math.min(100,Math.floor(25+10*(tier+1)));S.gold+=convertedGold;gainXP(2);return {duplicate:true,name:`${prefix} ${species}`,species,rarity,race:race.name,raceMult:race.mult,shards,convertedGold};}S.nextUnitId++;const tier=RARITIES.findIndex(r=>r[0]===rarity);const base=Math.round((8+Math.pow(tier+1,2)*4+(Math.min(S.wave,CAMPAIGN_MAX_WAVE)*.18))*race.mult*globalBoost());const unit={id:n,name:`${prefix} ${species}`,species,rarity,race:race.name,raceMult:race.mult,element,level:1,xp:0,power:Math.max(1,Math.round(base*1.5)),baseMaxHp:Math.round((90+base*3)*1.5),maxHp:Math.round((90+base*3)*1.5*(1+Math.max(0,(S.upgrades.health||1)-1)*.12)),hp:Math.round((90+base*3)*1.5*(1+Math.max(0,(S.upgrades.health||1)-1)*.12)),v14UnitBoost:true,spriteSeed:`${prefix}-${species}-${rarity}-${race.name}`,abilities:[],gear:{},knockedOut:false};S.units.push(unit);gainXP(6);return unit;}
function grantUnitXP(u,amount){if(!u||u.level>=1000)return;u.xp=(u.xp||0)+Math.max(0,Math.floor(amount));while(u.level<1000&&u.xp>=u.level*10){u.xp-=u.level*10;u.level++;u.power=Math.floor(u.power*1.045);u.baseMaxHp=Math.floor((u.baseMaxHp||u.maxHp)*1.04);u.maxHp=Math.floor(u.maxHp*1.04);u.hp=Math.min(u.maxHp,Math.round(u.hp*1.04));}}
function gainXP(amount){if(S.playerLevel>=500){S.xp=0;return}S.xp+=Math.max(0,Math.floor(amount))*2;let needed=100+(S.playerLevel-1)*35;while(S.xp>=needed&&S.playerLevel<500){S.xp-=needed;S.playerLevel++;S.skillPoints++;needed=100+(S.playerLevel-1)*35;notify(`Level up! Level ${S.playerLevel} · +1 skill point`);}}
function globalBoost(){return 1+(S.prestigeCount||0)*.1;}
function unitPower(u){let gearD=0;for(const id of Object.values(u.gear||{})){const g=GEAR.find(x=>x.id===id);if(g&&g.bonus.damage)gearD+=g.bonus.damage;}const abilityD=(u.abilities||[]).reduce((a,id)=>a+(ABILITIES.find(x=>x.name===id)?.type==='burst'?0.08:0),0);const ev=activeEvent();const eventMult=ev.active&&(ev.type==='attack'||ev.type==='crit')?(ev.type==='crit'?2.5:2):1;const guildMult=1+(S.guild.level||1)*.01;return Math.floor(u.power*(1+Math.max(0,(S.upgrades.damage||1)-1)*.12+gearBonus('damage')+gearD+abilityD)*globalBoost()*eventMult*guildMult);}
function gearBonus(key){const gear=Object.values(S.equippedGear||{}).reduce((a,id)=>{const g=GEAR.find(x=>x.id===id);return a+(g?.bonus?.[key]||0)},0);const base={starter:{hp:.05},'moon-garden':{luck:.05},'ember-forge':{damage:.08},'skyport':{damage:.05},'verdant-sanctum':{hp:.08},'void-observatory':{luck:.08}}[S.baseCosmetic]||{};return gear+(base[key]||0)}
function totalPower(){return S.team.reduce((a,id)=>a+unitPower(S.units.find(u=>u.id===id)||{power:0}),0)}function activeUnits(){return S.team.map(id=>S.units.find(u=>u.id===id)).filter(Boolean)}
