function addTeam(id){if(!S.units.some(u=>u.id===id))return;if(S.team.includes(id)){notify('That unit is already in your team.');return}if(S.team.length>=teamSlotLimit()){notify(`Formation full: ${teamSlotLimit()} troop slots at this milestone.`);return}const u=S.units.find(x=>x.id===id);if(u.hp<=0){notify('This unit is knocked out. It can recover only through a healer or its own skill.');return}S.team.push(id);save();render();notify(`${u.name} added to formation.`)}
function removeTeam(id){S.team=S.team.filter(x=>x!==id);save();render();notify('Unit returned to inventory. It is still owned.');}
function isUnlocked(w){return S.wave>=w||S.checkpoint>=w||(Array.isArray(S.unlocked)&&S.unlocked.includes(w))}function checkUnlocks(){for(const m of MILESTONES){if(S.wave>=m.wave&&!S.unlocked.includes(m.wave)){S.unlocked.push(m.wave);if(m.wave>0)notify(`Milestone reached: ${m.title}`)}}for(const w of checkpointWaves()){if(S.wave>=w&&!S.unlocked.includes('checkpoint-'+w))S.unlocked.push('checkpoint-'+w)}}
function recommendedPower(wave){const e=enemyFor(wave,'campaign');return Math.max(100,Math.floor(e.maxHp*.22+e.attack*35));}
function maxRecommendedWave(){const power=totalPower();let max=Math.max(0,Math.min(CAMPAIGN_MAX_WAVE,S.wave));for(let w=Math.max(0,S.wave+1);w<=CAMPAIGN_MAX_WAVE;w++){if(recommendedPower(w)<=power)max=w;else break;}return max;}
function enemyFor(wave,mode='campaign'){const boss=(mode==='campaign'&&wave>0&&wave%10===0)||(mode==='endless'&&wave%10===0)||(mode==='tower'&&S.tower.floor%5===0);const effective=Math.max(0,wave);const scale=mode==='campaign'?Math.pow(1.045,Math.min(effective,CAMPAIGN_MAX_WAVE)):mode==='endless'?Math.pow(1.12,Math.min(80,Math.max(0,wave-1))):Math.pow(1.16,Math.min(40,Math.max(0,S.tower.floor-1)));const count=mode==='campaign'?Math.min(5,1+Math.floor(effective/100)):1;const hp=Math.floor((mode==='campaign'?80:mode==='endless'?180:250)*scale*(boss?4.5:1)*count);const name=boss?['Rift Tyrant','Frostbound Monarch','Ashen Behemoth','The Hollow King'][(Math.floor(wave/10))%4]:['Meadow Scout','Rift Hound','Crystal Sentinel','Ember Stalker','Voidling','Starbound Knight','Grave Archer','Runic Brute','Storm Lancer','Dread Priest'][(effective+Math.floor(effective/7))%10];return {name,hp,maxHp:hp,attack:Math.max(3,Math.floor((8+Math.min(effective,CAMPAIGN_MAX_WAVE)*.55)*Math.pow(1.015,Math.min(effective,CAMPAIGN_MAX_WAVE)/4)*(boss?1.8:1))),boss,mode,count,level:Math.max(1,Math.floor(effective/5)+1)};}
function prepareEnemy(){S.wave=clamp(Math.floor(S.wave||0),0,CAMPAIGN_MAX_WAVE);enemy=enemyFor(S.wave);enemyHp=enemy.maxHp;enemyMax=enemy.maxHp;updateBattleUI();}
function healTeam(){/* no between-wave recovery; healing only comes from unit skills */}
function fightCampaign(){if(battleBusy)return;if(!enemy){notify('The next wave is already being prepared.');return}if(!S.team.length){notify('Summon units and add them to your team first.');return}if(activeUnits().every(u=>u.hp<=0)){handleTeamDefeat();return}battleBusy=true;const alive=activeUnits().filter(u=>u.hp>0);let damage=Math.max(1,alive.reduce((a,u)=>a+unitPower(u),0));let log=`Your team dealt ${fmt(damage)} damage to ${enemy.count||1} enemy troop${(enemy.count||1)===1?'':'s'}.`;for(const u of alive){for(const abilityName of (u.abilities||[]).slice(0,1)){const ab=ABILITIES.find(x=>x.name===abilityName);if(ab&&Math.random()<ab.chance){if(ab.type==='burst')damage+=Math.floor(unitPower(u)*ab.value);if(ab.type==='heal')u.hp=Math.min(u.maxHp,u.hp+Math.floor(u.maxHp*ab.value));if(ab.type==='burn')damage+=Math.floor(enemyMax*ab.value*2);if(ab.type==='freeze'){damage+=Math.floor(unitPower(u)*Math.max(.5,ab.value||.5));log+=` ${u.name} froze the target!`;}}}if(u.element==='bloom'&&u.hp>0)u.hp=Math.min(u.maxHp,u.hp+Math.ceil(u.maxHp*.015));}enemyHp=Math.max(0,enemyHp-damage);if(enemyHp<=0){winCampaign(log);battleBusy=false;updateBattleUI();save();render();return;}const living=activeUnits().filter(u=>u.hp>0);for(const u of living){const healer=alive.some(a=>a.element==='bloom'&&a.hp>0);const ev=activeEvent();const eventHp=ev.active&&ev.type==='hp';const guildMitigation=Math.min(.35,(S.guild.level||1)*.008);const taken=Math.max(1,Math.floor(enemy.attack/Math.max(1,living.length)*(eventHp?.5:1)*(1-guildMitigation)*(1-Math.min(.6,gearBonus('hp')*.3))));u.hp=Math.max(0,u.hp-taken);if(u.hp===0)u.knockedOut=true;if(healer&&u.hp>0)u.hp=Math.min(u.maxHp,u.hp+Math.ceil(u.maxHp*.025));}document.getElementById('battle-log').textContent=`${log} Enemy troops retaliate; damage persists between waves.`;battleBusy=false;updateBattleUI();save();renderTeam();if(activeUnits().every(u=>u.hp<=0))handleTeamDefeat();}
function handleTeamDefeat(){S.losses++;S.auto=false;S.wave=clamp(Math.floor(S.wave||0),0,CAMPAIGN_MAX_WAVE);for(const u of S.units){u.hp=u.maxHp;u.knockedOut=false;}enemy=null;enemyHp=0;enemyMax=0;prepareEnemy();save();render();notify(`Team defeated. Retry wave ${S.wave}, or manually choose any checkpoint you have completed. All owned units recovered.`);}
function winCampaign(log='Victory!'){if(!enemy||S.wave<0||S.wave>CAMPAIGN_MAX_WAVE)return;S.wins++;S.dailyWins=(S.dailyWins||0)+1;S.weeklyWins=(S.weeklyWins||0)+1;const defeatedWave=S.wave;const boss=enemy?.boss;const rewardsEnabled=defeatedWave<=CAMPAIGN_MAX_WAVE;let gold=0,xp=0;if(rewardsEnabled){const ev=activeEvent();const rewardMult=ev.active&&ev.type==='xp'?2:1;const unitXP=Math.max(1,Math.floor((5+Math.floor(defeatedWave/5))*globalBoost()*rewardMult));for(const u of activeUnits())if(u.hp>0)grantUnitXP(u,unitXP);gold=Math.floor((2+defeatedWave*2+(boss?15:0))*(1+Math.max(0,S.upgrades.shards-1)*.09)*globalBoost()*(ev.active&&ev.type==='gold'?2:1)*2);xp=Math.floor((20+defeatedWave*1.5)*globalBoost()*rewardMult);S.gold+=gold;gainXP(xp);if(Math.random()<Math.min(.85,(.12+Math.max(0,S.upgrades.shards-1)*.09)*globalBoost()*(ev.active&&ev.type==='shards'?2:1)))S.shards++;if(boss){S.shards+=1;if(defeatedWave>=50&&Math.random()<.18){const drops=GEAR.filter(x=>!['chrono-gear','fortune-prism','abyss-edge','star-mail'].includes(x.id));const drop=drops[Math.floor(Math.random()*drops.length)];if(!S.gear.includes(drop.id)){S.gear.push(drop.id);notify(`Rare boss equipment drop: ${drop.name}!`)}else S.gold+=Math.floor(gold*.5)}}}S.wave=Math.min(CAMPAIGN_MAX_WAVE,defeatedWave+1);if(isCheckpointWave(defeatedWave)&&defeatedWave>S.checkpoint){S.checkpoint=defeatedWave;notify(`Checkpoint secured! You completed wave ${defeatedWave}. Defeat now returns you to wave ${defeatedWave+1}.`)}checkUnlocks();enemy=null;enemyHp=0;enemyMax=0;if(defeatedWave>=CAMPAIGN_MAX_WAVE){S.wave=CAMPAIGN_MAX_WAVE;document.getElementById('battle-log').textContent='Campaign complete! Wave 300 secured. You have reached the end of the campaign.';}else document.getElementById('battle-log').textContent=`${log} Victory! +${fmt(gold)} gold · +${fmt(xp)} XP. Reward claimed automatically.`;document.getElementById('reward-gold').textContent=rewardsEnabled?`+${fmt(gold)} Gold`:'Campaign rewards claimed';document.getElementById('reward-xp').textContent=rewardsEnabled?`+${fmt(xp*2)} XP`:'0 XP';document.getElementById('reward-shards').textContent=rewardsEnabled?'Shard chance + boss bonus':'Shard chance + boss bonus';updateBattleUI();save();render();}
function startNextWave(){if(enemy&&enemyHp>0)return;prepareEnemy();save();renderBattle();}
function doSummons(){if(battleBusy)return;const cost=250*rollCount;if(S.gold<cost){notify(`You need ${fmt(cost)} gold for ${rollCount}× summons.`);return}S.gold-=cost;S.dailySummons=(S.dailySummons||0)+rollCount;S.weeklySummons=(S.weeklySummons||0)+rollCount;const got=[];for(let i=0;i<rollCount;i++)got.push(makeUnit());save();render();const result=document.getElementById('summon-result');result.innerHTML=got.map(u=>u.duplicate?`<div class="result-card rarity-${u.rarity} duplicate-card"><div><b>♻ Duplicate converted</b><small>${esc(u.name)} · ${u.rarity} ${u.race}<br>+${u.shards} shards · +${fmt(u.convertedGold)} gold</small></div></div>`:`<div class="result-card rarity-${u.rarity}">${sprite(u.spriteSeed,u.rarity)}<div><b>${esc(u.name)}</b><small>${u.rarity} · ${u.race} · ${u.raceMult}× stats</small></div></div>`).join('');const added=got.filter(u=>!u.duplicate).length,dupes=got.length-added;notify(`${added} new unit${added===1?'':'s'} added${dupes?`; ${dupes} duplicate${dupes===1?'':'s'} converted to shards and gold`:''}.`);}
function rollAbility(){const select=document.getElementById('ability-unit-select');const unitId=Number(select.value);const u=S.units.find(x=>x.id===unitId);if(!u){notify('Select a specific unit first.');return}if(S.shards<3){notify('You need 3 shards for an ability roll.');return}if((u.abilities||[]).length&&(u.abilityLocked||document.getElementById('lock-current-ability').checked)){notify('This unit’s ability is locked. Unlock it from the inventory before replacing.');return}if((u.abilities||[]).length&&!confirm(`Replace ${u.name}'s current ability? This costs 3 shards and the old ability will be lost.`))return;S.shards-=3;const weights=ABILITIES.map(a=>Math.pow(.32,Math.max(0,RARITIES.findIndex(r=>r[0]===a.rarity))));let r=Math.random()*weights.reduce((a,b)=>a+b,0),ab=ABILITIES[0];for(let i=0;i<ABILITIES.length;i++){r-=weights[i];if(r<=0){ab=ABILITIES[i];break}}S.abilityPity=(S.abilityPity||0)+1;if(S.abilityPity>=30&&RARITIES.findIndex(x=>x[0]===ab.rarity)<2){ab=ABILITIES.find(x=>x.rarity==='Epic')||ABILITIES[2];S.abilityPity=0}else if(RARITIES.findIndex(x=>x[0]===ab.rarity)>=2)S.abilityPity=0;u.abilities=[ab.name];u.abilityLocked=false;document.getElementById('ability-result').innerHTML=`<b>${ab.icon} ${esc(ab.name)} · ${esc(ab.rarity)}</b><p class="muted small">${esc(ab.desc)}</p><div class="unit-meta">Assigned directly to ${esc(u.name)}</div>`;save();render();notify(`${ab.name} assigned to ${u.name}.`)}
function assignAbility(abilityId,unitId){const a=S.abilities.find(x=>x.id===abilityId),u=S.units.find(x=>x.id===Number(unitId));if(!a||!u)return;if(u.abilityLocked){notify('This unit’s ability is locked.');return}if((u.abilities||[]).length&&!confirm(`Replace ${u.name}'s current ability with ${a.name}?`))return;u.abilities=[a.name];S.abilities=S.abilities.filter(x=>x.id!==abilityId);save();render();notify(`${a.name} assigned to ${u.name}.`)}
function trainUnit(id){const u=S.units.find(x=>x.id===Number(id));if(!u)return;if(u.level>=1000){notify('Unit level cap is 1,000.');return}const cost=u.level*100;if(S.gold<cost){notify(`Level ${u.level+1} requires ${fmt(cost)} gold (10 gold per XP).`);return}S.gold-=cost;S.dailyTraining=(S.dailyTraining||0)+1;u.level++;u.power=Math.floor(u.power*1.045);u.baseMaxHp=Math.floor((u.baseMaxHp||u.maxHp)*1.04);u.maxHp=Math.floor(u.maxHp*1.04);u.hp=Math.min(u.maxHp,Math.round(u.hp*1.04));save();render();notify(`${u.name} upgraded directly to level ${u.level} for ${fmt(cost)} gold.`)}
function toggleAbilityLock(id){const u=S.units.find(x=>x.id===Number(id));if(!u||!(u.abilities||[]).length){notify('This unit has no ability to lock yet.');return}u.abilityLocked=!u.abilityLocked;save();render();notify(`Ability ${u.abilityLocked?'locked':'unlocked'} for ${u.name}.`)}
function buyUpgrade(id){const up=UPGRADES.find(x=>x.id===id);if(!up)return;const level=S.upgrades[id]||1;if(level>=up.max){notify('That stat has reached its individual cap.');return}if(totalUpgradeLevels()>=500){notify('All 500 stat points have been allocated.');return}if(S.skillPoints<up.cost){notify('Not enough skill points. Level up by summoning and battling.');return}S.skillPoints-=up.cost;S.upgrades[id]=level+1;if(id==='health'){for(const u of S.units){const oldMax=Math.max(1,u.maxHp);const ratio=Math.max(0,Math.min(1,u.hp/oldMax));u.maxHp=Math.max(1,Math.floor((u.baseMaxHp||oldMax)*(1+Math.max(0,S.upgrades.health-1)*.12)));u.hp=Math.min(u.maxHp,Math.floor(ratio*u.maxHp));}}save();render();notify(`${up.name} upgraded to Lv ${level+1}. ${500-totalUpgradeLevels()} stat points remain.`)}
function equipGear(id,unitId){const g=GEAR.find(x=>x.id===id);if(!g||!S.gear.includes(id))return;const slot=['Weapon','Armor','Artifact','Ring'].includes(g.slot)?g.slot:'Artifact';g.slot=slot;const u=S.units.find(x=>x.id===Number(unitId));if(!u){S.equippedGear[slot]=id;notify(`${g.name} equipped in ${slot}.`)}else{u.gear=u.gear||{};u.gear[slot]=id;notify(`${g.name} equipped to ${u.name} (${slot}).`)}save();render();}
function gearOwned(id){return S.gear.includes(id)}
function renderHeader(){document.getElementById('gold').textContent=fmt(S.gold);document.getElementById('shards').textContent=fmt(S.shards);document.getElementById('gems').textContent=fmt(S.gems);document.getElementById('player-level').textContent=S.playerLevel;document.getElementById('wave-nav').textContent=`Wave ${S.wave}`;}
function renderBattle(){document.getElementById('wave-title').textContent=`Wave ${S.wave} · ${enemy?.name||'Preparing encounter'}`;document.getElementById('wave-number').textContent=S.wave;document.getElementById('wave-type').textContent=enemy?.boss?'BOSS ENCOUNTER':`LEVEL ${enemy?.level||1} · ${enemy?.count||1} ENEMY TROOP${(enemy?.count||1)===1?'':'S'}`;document.getElementById('enemy-name').textContent=enemy?.name||'Victory';document.getElementById('enemy-desc').textContent=enemy?.boss?'A boss with increased health and bonus drops.':'Enemy strength scales through 300 campaign waves; formations cap at five units.';document.getElementById('enemy-sprite').innerHTML=Array.from({length:Math.max(1,Math.min(5,enemy?.count||1))},(_,i)=>`<span class="enemy-mini-sprite">${sprite(`${enemy?.name||'enemy'}-${i}`,enemy?.boss?'Godly':'Epic',70)}</span>`).join('');document.getElementById('enemy-hp-label').textContent=enemy?`${fmt(enemyHp)} / ${fmt(enemyMax)}`:'Ready for next wave';document.getElementById('enemy-hp-bar').style.width=`${enemyMax?enemyHp/enemyMax*100:0}%`;document.getElementById('team-count').textContent=`${S.team.length} / ${teamSlotLimit()}`;document.getElementById('team-power').textContent=fmt(totalPower());document.getElementById('reward-gold').textContent=`+${fmt(2+Math.min(S.wave,CAMPAIGN_MAX_WAVE)*2+((S.wave>0&&S.wave%10===0)?15:0))} Gold`; document.getElementById('reward-xp').textContent=`+${fmt(20+Math.min(S.wave,CAMPAIGN_MAX_WAVE)*1.5)} XP`;document.getElementById('progress-caption').textContent=`Wave ${S.wave.toLocaleString()} / ${CAMPAIGN_MAX_WAVE} · Prestige ${S.prestigeCount||0}/10 · Checkpoint ${S.checkpoint||0} · ${teamSlotLimit()} troop slots`;document.getElementById('campaign-progress').style.width=`${Math.min(100,S.wave/CAMPAIGN_MAX_WAVE*100)}%`;const need=recommendedPower(S.wave),allowed=maxRecommendedWave();const guide=document.getElementById('wave-power-guidance');if(guide)guide.textContent=`Recommended power for wave ${S.wave}: ${fmt(need)} · Your team: ${fmt(totalPower())}. ${totalPower()>=need?'Your team meets this wave recommendation.':'Your team is below the recommendation.'} Estimated power frontier: wave ${allowed}. Start options are limited to checkpoints you have already completed.`;renderTeam();}
function unitCard(u,action){const equipped=S.team.includes(u.id);return `<article class="unit-card rarity-${u.rarity}"><div class="unit-sprite">${sprite(u.spriteSeed,u.rarity)}</div><div class="unit-name">${esc(u.name)}</div><div class="unit-meta">${u.rarity} · Lv ${u.level}</div><div class="unit-meta">${esc(u.race)} <span class="race-tag">${u.raceMult>1?`${u.raceMult}× STATS`:''}</span></div><div class="unit-stats"><span>⚔ ${fmt(unitPower(u))}</span><span>♥ ${fmt(u.hp)}/${fmt(u.maxHp)}</span></div>${u.abilities?.length?`<div class="unit-meta">◇ ${u.abilities.map(esc).join(', ')} ${u.abilityLocked?'🔒 LOCKED':''}</div><button class="button secondary full" data-lock-ability="${u.id}">${u.abilityLocked?'Unlock ability':'Lock ability'}</button>`:''}<div class="unit-train"><button class="button secondary" data-train-unit="${u.id}" ${u.level>=1000?'disabled':''}>Upgrade +1 level · ${fmt(u.level*100)} gold</button><span class="tag">Lv ${u.level}/1,000 · Battle XP ${u.xp||0}/${u.level*10}</span></div><button class="button ${equipped?'secondary':'primary'}" data-unit-action="${equipped?'remove':'add'}" data-id="${u.id}">${equipped?'Remove from team':'Add to team'}</button></article>`;}
function renderTeam(){const team=activeUnits();document.getElementById('battle-team').innerHTML=team.length?team.map(u=>`<article class="unit-card rarity-${u.rarity}"><div class="unit-sprite">${sprite(u.spriteSeed,u.rarity)}</div><div class="unit-name">${esc(u.name)}</div><div class="unit-meta">${u.rarity} · ${esc(u.race)}</div><div class="unit-stats"><span>⚔ ${fmt(unitPower(u))}</span><span>♥ ${fmt(u.hp)}/${fmt(u.maxHp)}</span></div></article>`).join(''):'<div class="empty">No units equipped yet. Summon units, then add them from Unit Inventory.</div>';document.getElementById('team-count').textContent=`${team.length} / ${teamSlotLimit()}`;document.getElementById('team-power').textContent=fmt(totalPower());}
function renderInventory(){const q=(document.getElementById('unit-search')?.value||'').toLowerCase(),r=document.getElementById('rarity-filter')?.value||'all',sort=document.getElementById('sort-units')?.value||'power';const units=S.units.filter(u=>(r==='all'||u.rarity===r)&&`${u.name} ${u.race} ${u.element}`.toLowerCase().includes(q));units.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='level'?b.level-a.level:sort==='rarity'?RARITIES.findIndex(x=>x[0]===b.rarity)-RARITIES.findIndex(x=>x[0]===a.rarity):unitPower(b)-unitPower(a));const team=activeUnits();document.getElementById('owned-count').textContent=S.units.length;document.getElementById('formation-count').textContent=`${S.team.length} / ${teamSlotLimit()}`;document.getElementById('storage-count').textContent=`${S.units.length-S.team.length} units`;document.getElementById('formation-grid').innerHTML=team.length?team.map(unitCard).join(''):'<div class="empty">Your formation is empty. Add a unit below.</div>';document.getElementById('inventory-grid').innerHTML=units.filter(u=>!S.team.includes(u.id)).length?units.filter(u=>!S.team.includes(u.id)).map(unitCard).join(''):'<div class="empty">No matching stored units. Summons are added here automatically.</div>';}
function renderOdds(){const autoBox=document.getElementById('auto-summon');if(autoBox)autoBox.checked=!!S.autoSummon;document.getElementById('rarity-table').innerHTML=RARITIES.map(r=>`<div class="odds-row" style="--rarity:${r[2]}"><span class="odds-dot"></span><span>${r[0]}</span><b>${(r[1]/100).toLocaleString('en-US',{maximumFractionDigits:2})}%</b></div>`).join('');document.getElementById('race-table').innerHTML=RACE_ODDS.map(r=>`<div class="odds-row" style="--rarity:${r[0]==='Demonic'?'#ff6d8e':'#93a7c8'}"><span class="odds-dot"></span><span>${r[0]} · ${r[2]}× stats</span><b>${(r[1]/100).toLocaleString('en-US',{maximumFractionDigits:2})}%</b></div>`).join('');document.getElementById('luck-multiplier').textContent=`${(1+Math.max(0,S.upgrades.luck-1)*.075+gearBonus('luck')+(S.endless.equipped?.1:0)).toFixed(2)}×`;document.getElementById('summons-made').textContent=fmt(S.summonsMade);document.getElementById('unique-count').textContent=S.units.length;const luck=1+S.upgrades.luck*.025+gearBonus('luck')+(S.endless.equipped?.1:0);const weights=RARITIES.map((r,i)=>i===0?r[1]/luck:r[1]*Math.pow(luck,Math.min(i,5)*.55));const total=weights.reduce((a,b)=>a+b,0);document.getElementById('rarity-table').innerHTML=RARITIES.map((r,i)=>`<div class="odds-row" style="--rarity:${r[2]}"><span class="odds-dot"></span><span>${r[0]}</span><b>${(weights[i]/total*100).toLocaleString('en-US',{maximumFractionDigits:4})}%</b></div>`).join('');const index=[];for(const prefix of PREFIXES)for(const species of SPECIES)index.push(`${prefix} ${species}`);document.getElementById('unit-index').innerHTML=`<div class="index-count">${index.length} catalog entries · ${S.units.length} owned units</div><div class="index-grid">${index.map(name=>`<span class="index-entry">${esc(name)}</span>`).join('')}</div>`;}
function renderAbilities(){const shardBalance=document.getElementById('ability-shards');if(shardBalance)shardBalance.textContent=fmt(S.shards);const abilityWeights=ABILITIES.map(a=>Math.pow(.32,Math.max(0,RARITIES.findIndex(r=>r[0]===a.rarity)))),abilityTotal=abilityWeights.reduce((a,b)=>a+b,0);document.getElementById('ability-index').innerHTML=RARITIES.map(r=>{const group=ABILITIES.map((a,i)=>({...a,weight:abilityWeights[i]})).filter(a=>a.rarity===r[0]);if(!group.length)return '';return `<section class="ability-rarity-group"><h3 style="color:${r[2]}">${esc(r[0])} <span>${group.length} ${group.length===1?'ability':'abilities'}</span></h3>${group.map(a=>`<div class="ability-index-row"><span class="ability-icon">${a.icon}</span><div><b>${esc(a.name)}</b><small>${esc(a.desc)}</small></div><strong>${(a.weight/abilityTotal*100).toFixed(2)}%</strong></div>`).join('')}</section>`}).join('');const sel=document.getElementById('ability-unit-select');if(sel){const old=sel.value;sel.innerHTML='<option value="">Choose a unit…</option>'+S.units.map(u=>`<option value="${u.id}">${esc(u.name)} · ${esc(u.rarity)}${u.abilities?.length?' · has ability':''}</option>`).join('');if(S.units.some(u=>String(u.id)===old))sel.value=old;else if(S.selectedAbilityUnit&&S.units.some(u=>u.id===S.selectedAbilityUnit))sel.value=String(S.selectedAbilityUnit);const selected=S.units.find(u=>u.id===Number(sel.value));document.getElementById('lock-current-ability').checked=!!selected?.abilityLocked}document.getElementById('ability-pity-label').textContent=`${S.abilityPity||0} / 30`;document.getElementById('ability-pity-bar').style.width=`${Math.min(100,(S.abilityPity||0)/30*100)}%`;document.getElementById('ability-inventory').innerHTML=S.abilities.length?S.abilities.map(a=>`<div class="ability-item"><div class="ability-icon">${a.icon}</div><div><b>${esc(a.name)} <span class="muted">· ${esc(a.rarity)}</span></b><small>${esc(a.desc)}</small></div></div>`).join(''):'<div class="empty">No abilities yet. Roll using shards to get started.</div>';}
function gearRarity(g){if(['transcendent-edge'].includes(g.id))return 'Transcendent';if(['eternal-compass'].includes(g.id))return 'Eternal';if(['wyrmcleaver','eclipse-signet'].includes(g.id))return 'Secret';if(['star-mail','fortune-prism'].includes(g.id))return 'Divine';if(['chrono-gear','abyss-edge'].includes(g.id))return 'Godly';if(['ember-ring','aurora-plate'].includes(g.id))return 'Mythic';if(['frost-crown','iron-aegis'].includes(g.id))return 'Legendary';if(['lucky-charm'].includes(g.id))return 'Epic';return 'Rare';}
function renderGear(){for(const g of GEAR)if(!['Weapon','Armor','Artifact','Ring'].includes(g.slot))g.slot=g.id==='ember-ring'?'Ring':g.id==='iron-aegis'||g.id==='frost-crown'||g.id==='star-mail'?'Armor':g.id==='abyss-edge'?'Weapon':'Artifact';document.getElementById('gear-summary').textContent=Object.values(S.equippedGear).length?Object.values(S.equippedGear).map(id=>GEAR.find(g=>g.id===id)?.name).filter(Boolean).join(' · '):'No gear equipped';document.getElementById('equipment-grid').innerHTML=['Weapon','Armor','Artifact','Ring'].map(slot=>`<div class="equipment-category"><div class="panel-heading"><h2>${slot}</h2><span class="tag">${GEAR.filter(g=>g.slot===slot).length} items</span></div><div class="equipment-category-grid">${GEAR.filter(g=>g.slot===slot).map(g=>{const owned=gearOwned(g.id),artifact=['chrono-gear','fortune-prism'].includes(g.id);return `<article class="gear-card rarity-${gearRarity(g)}"><div class="gear-icon">${g.icon}</div><div class="eyebrow">${gearRarity(g).toUpperCase()} · ${g.slot.toUpperCase()} · ${g.source.toUpperCase()}</div><h3>${g.name}</h3><p>${g.desc}</p><span class="tag">${owned?'Owned':'Not found'}</span><button class="button ${owned?'secondary':'primary'}" data-gear="${g.id}" ${!owned?'disabled':''}>${owned?(S.equippedGear[g.slot]===g.id?'Equipped':'Equip globally'):'Earn from mode'}</button></article>`}).join('')}</div></div>`).join('');}
function renderUpgrades(){document.getElementById('skill-points').textContent=S.skillPoints;document.getElementById('upgrade-level').textContent=`${S.playerLevel} · ${totalUpgradeLevels()}/500 stat points used`;document.getElementById('upgrade-grid').innerHTML=UPGRADES.map(u=>{const lv=S.upgrades[u.id]||1;const allocated=Math.max(0,lv-1);const effect=u.id==='damage'?`+${allocated*12}% unit damage`:u.id==='health'?`+${allocated*12}% unit max HP`:u.id==='luck'?`Luck factor ×${(1+allocated*.075).toFixed(2)}`:u.id==='race'?`+${allocated*12}% race weighting`:`+${allocated*9}% shard rewards`;return `<article class="upgrade-card"><div class="upgrade-head"><span class="upgrade-icon">${u.icon}</span><span class="tag">${allocated} points · Lv ${lv}</span></div><h3>${u.name}</h3><p>${u.desc}</p><strong class="upgrade-effect">${effect}</strong><div class="bar"><span style="width:${Math.min(100,allocated/500*100)}%;background:var(--purple)"></span></div><button class="button primary" data-upgrade="${u.id}" ${lv>=u.max||S.skillPoints<u.cost||totalUpgradeLevels()>=500?'disabled':''}>${totalUpgradeLevels()>=500?'500 POINTS USED':lv>=u.max?'STAT MAXED':'Upgrade · 1 point'}</button></article>`}).join('');}
function questCycle(){const now=new Date();const day=now.toISOString().slice(0,10);const jan=new Date(Date.UTC(now.getUTCFullYear(),0,1));const week=`${now.getUTCFullYear()}-W${Math.ceil((((now-jan)/86400000)+jan.getUTCDay()+1)/7)}`;if(S.questDay!==day){S.questDay=day;S.dailyQuestClaims=[];S.dailyWins=0;S.dailySummons=0;S.dailyTraining=0;S.dailyQuestSeed=(S.dailyQuestSeed||0)+1;}if(S.questWeek!==week){S.questWeek=week;S.weeklyQuestClaims=[];S.weeklyWins=0;S.weeklySummons=0;S.weeklyQuestSeed=(S.weeklyQuestSeed||0)+1;}S.dailyQuestClaims=S.dailyQuestClaims||[];S.weeklyQuestClaims=S.weeklyQuestClaims||[];return {day,week};}
function renderQuests(){questCycle();const qs=[{id:'d-summon',cycle:'daily',title:'Daily Summoner',desc:'Summon 3 creatures.',progress:Math.min(3,S.dailySummons||0),target:3,reward:'300 gold · 2 shards',done:(S.dailySummons||0)>=3,gold:300,shards:2},{id:'d-win',cycle:'daily',title:'Daily Patrol',desc:'Win 5 campaign encounters.',progress:Math.min(5,S.dailyWins||0),target:5,reward:'500 gold',done:(S.dailyWins||0)>=5,gold:500},{id:'d-level',cycle:'daily',title:'Daily Training',desc:'Own a unit at level 3 or higher.',progress:Math.min(3,S.dailyTraining||0),target:3,reward:'400 gold · 2 shards',done:(S.dailyTraining||0)>=3,gold:400,shards:2},{id:'w-boss',cycle:'weekly',title:'Weekly Boss Hunter',desc:'Defeat 3 campaign bosses.',progress:Math.min(3,Math.floor((S.weeklyWins||0)/10)),target:3,reward:'2,500 gold · 8 shards',done:(S.weeklyWins||0)>=30,gold:2500,shards:8},{id:'w-summon',cycle:'weekly',title:'Weekly Recruitment',desc:'Summon 15 creatures.',progress:Math.min(15,S.weeklySummons||0),target:15,reward:'2,000 gold · 10 shards',done:(S.weeklySummons||0)>=15,gold:2000,shards:10},{id:'w-wave',cycle:'weekly',title:'Weekly Expedition',desc:'Reach wave 50 or higher.',progress:Math.min(50,S.wave),target:50,reward:'3,000 gold · 12 shards',done:S.wave>=50,gold:3000,shards:12}];document.getElementById('quest-grid').innerHTML=qs.map(q=>{const claims=q.cycle==='daily'?S.dailyQuestClaims:S.weeklyQuestClaims;const claimed=claims.includes(q.id);return `<article class="quest-card"><div class="eyebrow">${q.cycle.toUpperCase()} QUEST · ${q.done?'COMPLETE':'ACTIVE'}</div><h3>${q.title}</h3><p>${q.desc}</p><div class="progress-caption"><span>Progress</span><b>${fmt(q.progress)} / ${q.target}</b></div><div class="bar"><span style="width:${Math.min(100,q.progress/q.target*100)}%;background:var(--purple)"></span></div><p>Reward: ${q.reward}</p><button class="button ${q.done&&!claimed?'primary':'secondary'}" data-quest="${q.id}" ${!q.done||claimed?'disabled':''}>${claimed?'Claimed':q.done?'Claim reward':'In progress'}</button></article>`}).join('');}
function renderBase(){const items=[{id:'starter',name:'Wayfarer Lanterns',icon:'✧',seed:'lantern-base',desc:'+5% team HP',bonus:{hp:.05},cost:0},{id:'moon-garden',name:'Moon Garden',icon:'☾',seed:'moon-garden-base',desc:'+5% summon luck',bonus:{luck:.05},cost:3000},{id:'ember-forge',name:'Ember Forge',icon:'♨',seed:'ember-forge-base',desc:'+8% team damage',bonus:{damage:.08},cost:4500},{id:'skyport',name:'Skyport Citadel',icon:'⌂',seed:'skyport-base',desc:'+5% troop damage',bonus:{damage:.05},cost:6500},{id:'verdant-sanctum',name:'Verdant Sanctum',icon:'❋',seed:'verdant-sanctum',desc:'+8% team HP',bonus:{hp:.08},cost:8000},{id:'void-observatory',name:'Void Observatory',icon:'✦',seed:'void-observatory',desc:'+8% summon luck',bonus:{luck:.08},cost:12000}];document.getElementById('base-bonuses').innerHTML=items.filter(x=>x.id===S.baseCosmetic).map(x=>`<span>${x.desc}</span>`).join('')||'<span>No cosmetic active</span>';const bs=document.getElementById('base-sprite');if(bs)bs.innerHTML=sprite(items.find(x=>x.id===S.baseCosmetic)?.seed||'starter-base','Divine',140);document.getElementById('cosmetic-grid').innerHTML=items.map(x=>`<article class="cosmetic-card"><div class="cosmetic-icon">${sprite(x.seed,'Divine',100)}</div><h3>${x.name}</h3><p>${x.desc}</p><button class="button ${S.baseCosmetic===x.id?'secondary':'primary'}" data-cosmetic="${x.id}" ${S.wave<75?'disabled':''}>${S.baseCosmetic===x.id?'Active':(S.baseCosmeticsOwned||['starter']).includes(x.id)?'Equip owned':x.cost===0?'Use cosmetic':`Buy · ${fmt(x.cost)} gold`}</button></article>`).join('');}
function randomGuildBossHp(){const tier=Math.min(5,1+Math.floor((S.guild.level-1)/6));return Math.floor((45000+Math.random()*155000)*tier*Math.pow(Math.max(1,S.guild.bossLevel),.35));}
function tickGuildBossDecay(){const g=S.guild;if(!g)return;const now=Date.now();if(!g.bossMaxHp||g.bossMaxHp<1){g.bossMaxHp=randomGuildBossHp();g.bossHp=g.bossMaxHp;g.bossDecayAt=now+30000+Math.random()*60000;}if(!g.bossDecayAt)g.bossDecayAt=now+30000+Math.random()*60000;if(now>=g.bossDecayAt&&g.bossHp>0){const loss=Math.max(1,Math.floor(g.bossMaxHp*(.005+Math.random()*.02)));g.bossHp=Math.max(1,g.bossHp-loss);g.bossDecayAt=now+30000+Math.random()*60000;save();}}
function renderGuild(){const g=S.guild;const now=new Date();const dayKey=now.toISOString().slice(0,10);const weekKey=`${now.getUTCFullYear()}-W${Math.ceil((Math.floor((now-new Date(Date.UTC(now.getUTCFullYear(),0,1)))/86400000)+new Date(Date.UTC(now.getUTCFullYear(),0,1)).getUTCDay()+1)/7)}`;if(g.dayKey!==dayKey){g.dayKey=dayKey;g.dailyContrib=0}if(g.weekKey!==weekKey){g.weekKey=weekKey;g.weeklyContrib=0}g.level=clamp(g.level||1,1,30);const bossCycle=g.level>=16?weekKey:dayKey;if(g.bossCycleKey!==bossCycle){g.bossCycleKey=bossCycle;g.bossHp=randomGuildBossHp();g.bossMaxHp=g.bossHp;g.bossLevel=1;g.lastBossAt=0;g.bossDecayAt=Date.now()+30000+Math.random()*60000;}tickGuildBossDecay();g.bossHp=Math.max(0,Number(g.bossHp)||0);g.bossMaxHp=Math.max(1,Number(g.bossMaxHp)||randomGuildBossHp());const hpPct=Math.max(0,Math.min(100,g.bossHp/g.bossMaxHp*100));document.getElementById('guild-level').textContent=g.level;document.getElementById('guild-xp-text').textContent=g.level>=30?'MAX LEVEL · 30':`${g.xp} / ${g.level*100} guild XP`;document.getElementById('guild-xp-bar').style.width=`${g.level>=30?100:g.xp/(g.level*100)*100}%`;document.getElementById('guild-boss-name').textContent=`${['Ancient Gatekeeper','Rift Wyrm','The Star Devourer','Eclipse Hydra','Worldroot Colossus'][Math.min(4,Math.floor((g.level-1)/6))]} · Lv ${g.bossLevel}`;document.getElementById('guild-boss-hp').textContent=`${fmt(g.bossHp)} / ${fmt(g.bossMaxHp)} HP · ${hpPct.toFixed(1)}%`;const bossNeed=Math.floor(g.bossMaxHp*Math.max(1,g.bossLevel)*.65);const bossPower=document.getElementById('guild-boss-power');if(bossPower)bossPower.textContent=`Recommended team power: ${fmt(bossNeed)} · Your power: ${fmt(totalPower())} · ${totalPower()>=bossNeed?'Ready for this boss':'Power below recommendation'}`;document.getElementById('guild-boss-bar').style.width=`${hpPct}%`;document.getElementById('guild-boss-sprite').innerHTML=sprite('guildboss'+g.bossLevel,'Godly');const members=document.getElementById('guild-members');if(members)members.innerHTML=[['You','Guild Leader',g.level>=20?'Veteran':'Active'],['Astra Vale','Damage Specialist','Active'],['Mira Dawn','Guild Healer','Active'],['Korrin Ash','Treasure Hunter','Weekly'],['Nyx Ember','Scout','Daily']].map((m,i)=>`<div class="guild-member"><span class="member-avatar">${['✦','⚔','✚','◇','☾'][i]}</span><span><b>${m[0]}</b><small>${m[1]}</small></span><em>${m[2]}</em></div>`).join('');const perk=document.getElementById('guild-perks');if(perk)perk.innerHTML=`<b>Guild Perks</b><div class="bonus-pills"><span>+${g.level*2}% troop HP</span><span>+${g.level}% troop damage</span><span>+${Math.floor(g.level/3)}% shard chance</span><span>${g.members||5} members</span></div>`;const cd=document.getElementById('guild-boss-cooldown');if(cd){const tier=Math.min(5,1+Math.floor((g.level-1)/6)),mins=[60,45,30,20,15][tier-1],left=mins*60000-(Date.now()-(g.lastBossAt||0));cd.textContent=left>0?`Tier ${tier} · ready in ${formatDuration(left)} · random HP decay active`:`Tier ${tier} · ready to challenge · random HP decay active`;document.getElementById('guild-boss-fight').disabled=left>0;}document.getElementById('guild-train').disabled=g.level>=30;document.getElementById('guild-train').textContent=g.level>=30?'Guild MAX LEVEL · 30':`Contribute ${fmt(g.level*500)} gold for 50 XP`;}
// Checkpoint selection is UI-only until the player presses Start Expedition. Never auto-select the latest checkpoint.
let selectedCheckpointStart=0;
function renderCheckpointSelector(){const options=document.getElementById('checkpoint-options');if(!options)return;const available=[0,...CHECKPOINTS.filter(w=>w<=S.checkpoint)];if(!available.includes(selectedCheckpointStart))selectedCheckpointStart=0;document.getElementById('checkpoint-unlocked-count').textContent=`${available.length} start${available.length===1?'':'s'} unlocked`;options.innerHTML=available.map(w=>{const selected=w===selectedCheckpointStart;const label=w===0?'Beginning':`Checkpoint ${w}`;const sub=w===0?'Start from wave 0':`Start at wave ${w}`;return `<button type="button" class="checkpoint-option ${selected?'selected':''}" data-checkpoint-start="${w}" aria-pressed="${selected}"><span class="checkpoint-option-icon">${selected?'✓':w===0?'⌂':'⚑'}</span><span class="checkpoint-option-copy"><b>${label}</b><small>${sub}</small></span><span class="checkpoint-option-state">${selected?'SELECTED':'UNLOCKED'}</span></button>`}).join('');const rec=recommendedPower(selectedCheckpointStart);document.getElementById('checkpoint-selected-summary').textContent=`${selectedCheckpointStart===0?'Beginning':`Checkpoint ${selectedCheckpointStart}`} · Wave ${selectedCheckpointStart} · Recommended power ${fmt(rec)} · Your team ${fmt(totalPower())}`;const guide=document.getElementById('wave-power-guidance');if(guide)guide.textContent=totalPower()>=rec?'Your team meets the recommended power for this starting point.':'Your team is below the recommended power for this starting point. You can still choose an unlocked checkpoint.';}
function startAtCheckpoint(){const target=selectedCheckpointStart;if(target!==0&&!CHECKPOINTS.includes(target)){notify('That is not a valid checkpoint.');return}if(target>S.checkpoint){notify(`Checkpoint ${target} is locked. Complete wave ${target} first to unlock it.`);return}S.wave=target;S.auto=false;for(const u of S.units){if(u.hp<=0){u.hp=u.maxHp;u.knockedOut=false}}enemy=null;enemyHp=0;enemyMax=0;prepareEnemy();save();render();go('battle');notify(target===0?'Campaign restarted from the beginning.':`Starting at completed checkpoint wave ${target}.`)}


function renderTower(){document.getElementById('tower-floor').textContent=S.tower.floor;const tb=document.getElementById('tower-enemy-bar');if(tb)tb.style.width=`${100/(1+S.tower.floor*.12)}%`;const th=document.getElementById('tower-enemy-hp');if(th)th.textContent=`${fmt(Math.floor(250*Math.pow(1.25,S.tower.floor-1)))} estimated HP · boss every 5 floors`; const cs=document.getElementById('tower-combat-sprites');if(cs)cs.innerHTML=`<div class="mode-squad">${activeUnits().slice(0,5).map(u=>sprite(u.spriteSeed,u.rarity,65)).join('')}</div><span class="mode-vs">VS</span>${sprite('tower-enemy-'+S.tower.floor,'Godly',90)}`;document.getElementById('tower-message').textContent=`Best floor: ${S.tower.best}. Reach floor 10 for Chrono Gear.`;document.getElementById('tower-artifact-status').textContent=S.tower.artifact?(S.tower.equipped?'Equipped':'Obtained'):'Not obtained';document.getElementById('equip-tower-artifact').disabled=!S.tower.artifact;}
function renderEndless(){document.getElementById('endless-floor').textContent=S.endless.floor;const eb=document.getElementById('endless-enemy-bar');if(eb)eb.style.width=`${100/(1+S.endless.floor*.08)}%`;const eh=document.getElementById('endless-enemy-hp');if(eh)eh.textContent=`${fmt(Math.floor(400*Math.pow(1.3,S.endless.floor-1)))} estimated HP · rewards every 25 waves`; const cs=document.getElementById('endless-combat-sprites');if(cs)cs.innerHTML=`<div class="mode-squad">${activeUnits().slice(0,5).map(u=>sprite(u.spriteSeed,u.rarity,65)).join('')}</div><span class="mode-vs">VS</span>${sprite('endless-enemy-'+S.endless.floor,'Secret',90)}`;document.getElementById('endless-message').textContent=`Best: wave ${S.endless.best}. Rewards every 25 waves.`;document.getElementById('endless-artifact-status').textContent=S.endless.artifacts.length?(S.endless.equipped?'Equipped':'Obtained'):'Not obtained';document.getElementById('equip-endless-artifact').disabled=!S.endless.artifacts.length;}
function renderEvents(){const cards=[['hp','♥','Titan Surge','All troop HP is doubled while active.'],['attack','⚔','Warpath','All troop attack is doubled while active.'],['luck','✧','Astral Fortune','Summon luck is doubled while active.'],['shards','◇','Shardfall','Shard drop chances are doubled while active.'],['xp','✦','Awakening','Player and unit XP are doubled while active.'],['gold','◈','Golden Hour','Campaign gold rewards are doubled while active.'],['crit','ϟ','Critical Tempest','Damage is boosted while active.']];const active=activeEvent();document.getElementById('event-grid').innerHTML=cards.map(e=>`<article class="event-card"><div class="event-symbol">${e[1]}</div><div class="eyebrow">${active.active&&active.type===e[0]?'ACTIVE NOW':'ROTATING WORLD EVENT'}</div><h3>${e[2]}</h3><p>${e[3]}</p><span class="tag">${active.active&&active.type===e[0]?'LIVE · '+formatDuration(active.left):'10 minutes each hour'}</span></article>`).join('');}
function render(){renderHeader();renderBattle();renderInventory();renderOdds();renderAbilities();renderGear();renderUpgrades();renderQuests();renderBase();renderGuild();renderTower();renderEndless();renderEvents();renderEventTimer();renderPrestige();renderCheckpointSelector();document.querySelectorAll('.nav[data-view]').forEach(b=>{const v=b.dataset.view,unlock=Number(b.dataset.unlock||0),locked=unlock&&!isUnlocked(unlock);b.classList.toggle('locked',!!locked);b.title=locked?`Unlock at wave ${unlock}`:'';b.querySelector('small')?.classList.toggle('locked-notice',!!locked)});}
function go(view,push=true){const el=document.getElementById('view-'+view);if(!el)return;const nav=document.querySelector(`.nav[data-view="${view}"]`),unlock=Number(nav?.dataset.unlock||0);if(unlock&&!isUnlocked(unlock)&&!S.adminUnlocked){notify(`Unlock this section at campaign wave ${unlock}.`);return}if(view!==currentView)previousView=currentView;currentView=view;document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${view}`));document.querySelectorAll('.nav[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.getElementById('sidebar').classList.remove('open');if(push)history.replaceState(null,'',`#${view}`);if(view==='summon')document.getElementById('altar-art').innerHTML=sprite('astralaltar','Divine');if(view==='battle')updateBattleUI();}
function back(){const target=previousView&&previousView!==currentView?previousView:'battle';go(target);}
function updateBattleUI(){renderBattle()}
function showMilestones(){const list=document.getElementById('milestone-list');const overview=document.getElementById('milestone-progress-overview');const unlocked=MILESTONES.filter(m=>S.wave>=m.wave||S.unlocked.includes(m.wave)).length;const next=MILESTONES.find(m=>m.wave>S.wave);const overall=Math.min(100,Math.floor(S.wave/CAMPAIGN_MAX_WAVE*100));overview.innerHTML=`<div class="milestone-overview-top"><div><span class="eyebrow">CAMPAIGN MILESTONES</span><h3>${unlocked} / ${MILESTONES.length} unlocked</h3></div><b>${overall}%</b></div><div class="bar milestone-overview-bar"><span style="width:${overall}%"></span></div><p class="muted small">${next?`Next milestone: ${next.title} at wave ${next.wave} · ${Math.max(0,next.wave-S.wave)} wave${next.wave-S.wave===1?'':'s'} to go.`:'All milestones reached. The campaign is complete.'}</p>`;list.innerHTML=MILESTONES.map(m=>{const done=S.wave>=m.wave||S.unlocked.includes(m.wave);const pct=done?100:m.wave===0?100:Math.max(0,Math.min(99,Math.floor(S.wave/m.wave*100)));return `<article class="milestone-item ${done?'done':'locked'}"><div class="milestone-wave">${m.wave===0?'START':`WAVE ${m.wave}`}</div><div class="milestone-main"><div class="milestone-title-row"><b>${m.title}</b><span class="milestone-status">${done?'✓ UNLOCKED':`🔒 ${m.wave-S.wave} TO GO`}</span></div><small>${m.desc}</small><div class="milestone-progress-line"><span style="width:${pct}%"></span></div><small class="milestone-requirement">${done?`Requirement met at wave ${m.wave}`:`Requirement: reach wave ${m.wave} · Progress ${Math.min(S.wave,m.wave)} / ${m.wave}`}</small></div></article>`}).join('');document.getElementById('milestone-modal').classList.add('open')}

function tutorial(){if(S.tutorialDone)return;const steps=[['Welcome to Mythic Frontier','You are a Realm Walker building a collection of fantasy creatures. Summon, train, equip and lead a balanced squad through a 300-wave campaign.'],['Summon and build your roster','Spend gold at the Summoning Altar. Your collection keeps one copy of each species-and-race combination. Duplicates automatically convert into shards and gold; add your best units to your formation from Unit Inventory. Shards power the Ability Gacha, which is available from wave 0.'],['Your formation grows','You start with 1 troop slot. Complete wave 10 for slot 2, wave 25 for slot 3, wave 100 for slot 4 and wave 200 for slot 5. Upgrade units one level at a time using gold; combat grants unit XP too.'],['Live auto-battle','Your team and enemies automatically exchange attacks while Campaign is open. There is no Fight button. Keep an eye on HP, choose healers and equip gear. Victories claim rewards automatically.'],['Checkpoints and recovery','You must defeat a checkpoint wave to secure it. Completing wave 10 saves checkpoint 10 and your next wave is 11. If your team falls, you return to the wave after your latest completed checkpoint and all owned units recover.'],['Long-term progression','Guild perks, Tower floors, Endless challenges, timed events, home-base cosmetics and four equipment slots give you more ways to improve. Complete wave 300 to unlock Prestige: wipe your collection, equipment, upgrades and modes; carry over up to 50,000 gold and earn +10% global boost, up to 10 times.']];function show(){document.getElementById('tutorial-title').textContent=steps[tutorialStep][0];document.getElementById('tutorial-copy').textContent=steps[tutorialStep][1];document.getElementById('tutorial-progress').style.width=`${(tutorialStep+1)/steps.length*100}%`;document.getElementById('tutorial-modal').classList.add('open');document.getElementById('tutorial-next').textContent=tutorialStep===steps.length-1?'Start playing':'Next tip →'}document.getElementById('tutorial-next').onclick=()=>{tutorialStep++;if(tutorialStep>=steps.length){S.tutorialDone=true;save();document.getElementById('tutorial-modal').classList.remove('open')}else show()};document.getElementById('tutorial-skip').onclick=()=>{S.tutorialDone=true;save();document.getElementById('tutorial-modal').classList.remove('open')};show()}
function claimQuest(id){questCycle();const defs={'d-summon':{cycle:'daily',can:()=>(S.dailySummons||0)>=3,gold:300,shards:2},'d-win':{cycle:'daily',can:()=>(S.dailyWins||0)>=5,gold:500},'d-level':{cycle:'daily',can:()=>(S.dailyTraining||0)>=3,gold:400,shards:2},'w-boss':{cycle:'weekly',can:()=>(S.weeklyWins||0)>=30,gold:2500,shards:8},'w-summon':{cycle:'weekly',can:()=>(S.weeklySummons||0)>=15,gold:2000,shards:10},'w-wave':{cycle:'weekly',can:()=>S.wave>=50,gold:3000,shards:12}};const q=defs[id];if(!q||!q.can())return;const claims=q.cycle==='daily'?S.dailyQuestClaims:S.weeklyQuestClaims;if(claims.includes(id))return;claims.push(id);S.gold+=(q.gold||0)*2;S.shards+=q.shards||0;save();render();notify(`${q.cycle==='daily'?'Daily':'Weekly'} quest claimed!`);}
function guildPerkText(){const l=S.guild.level;return `+${l*2}% troop HP · +${l}% troop damage · +${Math.floor(l/3)}% shard chance · Boss tier ${Math.min(5,1+Math.floor((l-1)/6))}`;}
function doGuildTrain(){if(S.guild.level>=30){notify('Guild has reached max level 30.');return}const coinCost=Math.max(500,S.guild.level*500);if(S.gold<coinCost){notify(`Need ${fmt(coinCost)} gold to contribute at guild level ${S.guild.level}.`);return}S.gold-=coinCost;S.guild.xp+=50;S.guild.weeklyContrib=(S.guild.weeklyContrib||0)+1;S.guild.dailyContrib=(S.guild.dailyContrib||0)+1;while(S.guild.level<30&&S.guild.xp>=S.guild.level*100){S.guild.xp-=S.guild.level*100;S.guild.level++}if(S.guild.level>=30)S.guild.xp=0;save();renderGuild();renderHeader();notify('Guild merit contributed. Guild perks improved.');}
function fightGuildBoss(){const now=Date.now(),tier=Math.min(5,1+Math.floor((S.guild.level-1)/6)),cooldown=(tier===1?60:tier===2?45:tier===3?30:tier===4?20:15)*60*1000;const remaining=cooldown-(now-(S.guild.lastBossAt||0));if(remaining>0){notify(`Guild boss cooldown: ${formatDuration(remaining)} remaining.`);return}S.guild.lastBossAt=now;const dmg=Math.max(1,Math.floor(totalPower()/Math.max(1,S.guild.bossLevel)));S.guild.bossHp=Math.max(0,S.guild.bossHp-dmg);if(S.guild.bossHp<=0){S.guild.bossLevel++;S.guild.bossHp=randomGuildBossHp();S.guild.bossMaxHp=S.guild.bossHp;S.guild.bossDecayAt=Date.now()+30000+Math.random()*60000;S.gold+=2000*tier;S.shards+=3+tier;S.guild.xp=Math.min(S.guild.level*100-1,S.guild.xp+100);const gear=GEAR.find(g=>g.id==='ember-ring');if(gear&&!S.gear.includes(gear.id))S.gear.push(gear.id);notify(`Guild boss defeated! Tier ${tier} rewards claimed.`)}else notify(`Guild boss took ${dmg} power damage. Next challenge in ${tier===1?'60':tier===2?'45':tier===3?'30':tier===4?'20':'15'} minutes.`);save();renderGuild();renderHeader();}
function formatDuration(ms){const s=Math.max(0,Math.ceil(ms/1000));return `${Math.floor(s/60)}m ${s%60}s`}
function fightTower(){const floor=S.tower.floor,need=Math.floor(250*Math.pow(1.25,floor-1));if(totalPower()<need){notify(`Your team needs ${fmt(need)} power for this floor.`);return}S.tower.best=Math.max(S.tower.best,floor);S.tower.floor++;S.gold+=Math.floor((300+floor*80)*globalBoost()*2);if(floor%10===9){S.tower.artifact=true;if(!S.gear.includes('chrono-gear'))S.gear.push('chrono-gear');notify('Tower milestone! Chrono Gear obtained.')}else notify(`Tower floor ${floor} cleared.`);save();renderTower();renderHeader();renderGear()}
function fightEndless(){const floor=S.endless.floor,need=Math.floor(400*Math.pow(1.3,floor-1));if(totalPower()<need){notify(`Your team needs ${fmt(need)} power for this endless wave.`);return}S.endless.best=Math.max(S.endless.best,floor);S.endless.floor++;S.gold+=Math.floor((500+floor*100)*globalBoost()*2);gainXP(Math.floor((25+floor*2)*globalBoost()));if(floor%25===24){const id=floor<50?'fortune-prism':'abyss-edge';if(!S.gear.includes(id))S.gear.push(id);S.endless.artifacts.push(id);notify(`Endless milestone reward: ${GEAR.find(g=>g.id===id).name}!`)}else notify(`Endless wave ${floor} cleared.`);save();renderEndless();renderHeader();renderGear()}
function claimEvent(id){notify('These are timed world boosts, not achievement quests. Play during the active event to benefit automatically.');}
function claimCosmetic(id){const c={starter:{cost:0},'moon-garden':{cost:3000},'ember-forge':{cost:4500},skyport:{cost:6500},'verdant-sanctum':{cost:8000},'void-observatory':{cost:12000}}[id];if(!c||S.wave<75)return;if(S.gold<c.cost){notify('Not enough gold.');return}S.gold-=c.cost;S.baseCosmetic=id;save();renderBase();renderHeader();notify('Base cosmetic activated. Bonuses are active while selected.')}
function unlockAdmin(){if(document.getElementById('admin-code').value!==ADMIN_PASSWORD){document.getElementById('admin-message').textContent='Incorrect code.';return}S.adminUnlocked=true;document.getElementById('admin-gate').classList.add('hidden');document.getElementById('admin-tools').classList.remove('hidden');document.getElementById('admin-message').textContent='Admin unlocked.';save();notify('Testing admin panel unlocked.')}
function adminLock(){S.adminUnlocked=false;document.getElementById('admin-tools').classList.add('hidden');document.getElementById('admin-gate').classList.remove('hidden');document.getElementById('admin-code').value='';save()}
function adminMilestones(){for(const m of MILESTONES)if(!S.unlocked.includes(m.wave))S.unlocked.push(m.wave);for(const w of checkpointWaves())if(!S.unlocked.includes('checkpoint-'+w))S.unlocked.push('checkpoint-'+w);S.wave=Math.max(S.wave,CAMPAIGN_MAX_WAVE);S.checkpoint=Math.max(S.checkpoint,CAMPAIGN_MAX_WAVE);checkUnlocks();save();render();notify('All milestones, checkpoints and modes unlocked.')}
function adminMaxUpgrades(){S.upgrades={damage:251,health:101,luck:51,race:51,shards:51};S.skillPoints=0;for(const unit of S.units){const ratio=unit.maxHp?unit.hp/unit.maxHp:1;unit.maxHp=Math.max(1,Math.floor((unit.baseMaxHp||unit.maxHp)*(1+(S.upgrades.health-1)*.12)));unit.hp=Math.min(unit.maxHp,Math.floor(unit.maxHp*ratio));}save();render();notify('Allocated 500 points: 250 damage, 100 HP, 50 luck, 50 race and 50 shard points.')}
function adminApplyValues(){if(!S.adminUnlocked){notify('Unlock the admin panel first.');return}const read=(id,min,max)=>clamp(Math.floor(Number(document.getElementById(id).value)||0),min,max);S.gold=read('admin-set-gold',0,Number.MAX_SAFE_INTEGER);S.shards=read('admin-set-shards',0,Number.MAX_SAFE_INTEGER);const wave=read('admin-set-wave',0,CAMPAIGN_MAX_WAVE);S.wave=wave;S.checkpoint=CHECKPOINTS.filter(w=>w<=wave).pop()||0;S.playerLevel=read('admin-set-level',1,500);S.xp=0;S.skillPoints=Math.max(0,S.playerLevel-totalUpgradeLevels());if(wave>=CAMPAIGN_MAX_WAVE){S.checkpoint=CAMPAIGN_MAX_WAVE;for(const m of MILESTONES)if(!S.unlocked.includes(m.wave))S.unlocked.push(m.wave)}enemy=null;enemyHp=0;enemyMax=0;checkUnlocks();save();render();go('battle');notify('Exact admin values applied: gold, shards, wave and player level.')} 
function adminResetData(){if(!S.adminUnlocked){notify('Unlock the admin panel first.');return}if(!confirm('Reset ALL Mythic Frontier save data on this browser? This cannot be undone.'))return;try{localStorage.removeItem(SAVE_KEY)}catch(e){}S=freshState();enemy=null;enemyHp=0;enemyMax=0;currentView='battle';save();render();go('battle');adminLock();notify('Save reset. A fresh campaign has started.');}
function activeEvent(){const now=Date.now();let start=S.events?.lastStart||0;if(!start||now-start>=3600000){S.events.lastStart=now;S.events.type=['hp','attack','luck','shards','xp','gold','crit'][Math.floor(Math.random()*7)];S.events.duration=600000;save();}const elapsed=now-S.events.lastStart;return elapsed<600000?{active:true,type:S.events.type,left:600000-elapsed}:{active:false,type:S.events.type,left:Math.max(0,3600000-elapsed)};}
function renderEventTimer(){const el=document.getElementById('event-timer');if(!el)return;const e=activeEvent();const names={hp:'Double HP',attack:'Double Attack',luck:'Double Summon Luck',shards:'Double Shards',xp:'Double Player & Unit XP',gold:'Double Gold',crit:'Critical Damage Surge'};el.innerHTML=e.active?`<b>LIVE EVENT: ${names[e.type]}</b><span>Ends in ${formatDuration(e.left)} · 10-minute boost</span>`:`<b>Next event in ${formatDuration(e.left)}</b><span>Events run for 10 minutes every hour.</span>`;document.body.classList.toggle('event-boost-hp',e.active&&e.type==='hp');document.body.classList.toggle('event-boost-attack',e.active&&(e.type==='attack'||e.type==='crit'));}
function prestigeReset(){if(S.wave<CAMPAIGN_MAX_WAVE||S.checkpoint<CAMPAIGN_MAX_WAVE){notify('Complete wave 300 before prestiging.');return}if((S.prestigeCount||0)>=10){notify('Prestige limit reached: 10/10.');return}if(!confirm(`Prestige and wipe your collection, gear, upgrades, shards, quests, guild and modes? Your gold alone carries over, capped at 50,000. You gain a permanent +10% global boost (${(S.prestigeCount||0)+1}/10).`))return;const nextPrestige=(S.prestigeCount||0)+1;const carriedGold=Math.min(50000,Math.max(0,Math.floor(S.gold||0)));S=freshState();S.prestigeCount=nextPrestige;S.gold=carriedGold;S.tutorialDone=true;S.upgrades={luck:1,damage:1,health:1,race:1,shards:1};enemy=null;enemyHp=0;enemyMax=0;currentView='battle';checkUnlocks();save();render();go('battle');notify(`Prestige ${nextPrestige}/10 complete. All progress reset except ${fmt(carriedGold)} gold; +${nextPrestige*10}% global boost.`);}
function renderPrestige(){const el=document.getElementById('prestige-status');if(el)el.textContent=`Prestige ${S.prestigeCount||0}/10 · Global boost +${(S.prestigeCount||0)*10}%`;const b=document.getElementById('prestige-button');if(b)b.disabled=S.wave<CAMPAIGN_MAX_WAVE||S.checkpoint<CAMPAIGN_MAX_WAVE||(S.prestigeCount||0)>=10;}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){e.preventDefault();go(nav.dataset.view);return}const close=e.target.closest('[data-close]');if(close){document.getElementById(close.dataset.close).classList.remove('open');return}const train=e.target.closest('[data-train-unit]');if(train){trainUnit(train.dataset.trainUnit);return}const lock=e.target.closest('[data-lock-ability]');if(lock){toggleAbilityLock(lock.dataset.lockAbility);return}const ua=e.target.closest('[data-unit-action]');if(ua){ua.dataset.unitAction==='add'?addTeam(Number(ua.dataset.id)):removeTeam(Number(ua.dataset.id));return}const up=e.target.closest('[data-upgrade]');if(up){buyUpgrade(up.dataset.upgrade);return}const gear=e.target.closest('[data-gear]');if(gear){equipGear(gear.dataset.gear);return}const quest=e.target.closest('[data-quest]');if(quest){claimQuest(quest.dataset.quest);return}const cosmetic=e.target.closest('[data-cosmetic]');if(cosmetic){claimCosmetic(cosmetic.dataset.cosmetic);return}const event=e.target.closest('[data-event]');if(event){claimEvent(event.dataset.event);return}});
document.getElementById('admin-unlock').addEventListener('click',unlockAdmin);document.getElementById('admin-code').addEventListener('keydown',e=>{if(e.key==='Enter')unlockAdmin()});document.getElementById('admin-milestones').addEventListener('click',adminMilestones);document.getElementById('admin-max-upgrades').addEventListener('click',adminMaxUpgrades);document.getElementById('admin-apply-values').addEventListener('click',adminApplyValues);document.getElementById('admin-reset').addEventListener('click',adminResetData);document.getElementById('prestige-button').addEventListener('click',prestigeReset);document.getElementById('admin-close').addEventListener('click',adminLock);document.getElementById('menu-toggle').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));document.querySelectorAll('[data-roll]').forEach(b=>b.addEventListener('click',()=>{rollCount=Number(b.dataset.roll);document.querySelectorAll('[data-roll]').forEach(x=>x.classList.toggle('selected',x===b));document.getElementById('roll-button').textContent=`✦ Roll ${rollCount===1?'summon':`${rollCount} summons`} · ${fmt(250*rollCount)} gold`}));document.getElementById('roll-button').addEventListener('click',doSummons);document.getElementById('auto-summon').addEventListener('change',e=>{S.autoSummon=e.target.checked;save();notify(S.autoSummon?'Auto-summon enabled while altar is open.':'Auto-summon paused.');});document.getElementById('ability-roll').addEventListener('click',rollAbility);document.getElementById('ability-unit-select').addEventListener('change',e=>{S.selectedAbilityUnit=Number(e.target.value)||null;const u=S.units.find(x=>x.id===S.selectedAbilityUnit);document.getElementById('lock-current-ability').checked=!!u?.abilityLocked;save()});document.getElementById('lock-current-ability').addEventListener('change',e=>{const u=S.units.find(x=>x.id===Number(document.getElementById('ability-unit-select').value));if(u&&u.abilities?.length){u.abilityLocked=e.target.checked;save();renderInventory();notify(`Ability ${u.abilityLocked?'locked':'unlocked'}.`)}else if(e.target.checked){e.target.checked=false;notify('Select a unit that already has an ability first.')}});document.getElementById('ability-inventory').addEventListener('change',e=>{if(e.target.matches('[data-assign]')&&e.target.value)assignAbility(e.target.dataset.assign,e.target.value)});['unit-search','rarity-filter','sort-units'].forEach(id=>document.getElementById(id).addEventListener(id==='unit-search'?'input':'change',renderInventory));document.getElementById('wave-milestones').addEventListener('click',showMilestones);document.getElementById('milestone-inline').addEventListener('click',showMilestones);document.getElementById('guild-train').addEventListener('click',doGuildTrain);document.getElementById('guild-boss-fight').addEventListener('click',fightGuildBoss);document.getElementById('checkpoint-start-button').addEventListener('click',startAtCheckpoint);document.getElementById('checkpoint-options').addEventListener('click',e=>{const button=e.target.closest('[data-checkpoint-start]');if(!button)return;const target=Number(button.dataset.checkpointStart);if(target!==0&&target>S.checkpoint){notify(`Checkpoint ${target} is locked. Complete it in the campaign first.`);return}selectedCheckpointStart=target;renderCheckpointSelector()});document.getElementById('tower-fight').addEventListener('click',fightTower);document.getElementById('endless-fight').addEventListener('click',fightEndless);document.getElementById('equip-tower-artifact').addEventListener('click',()=>{if(!S.tower.artifact)return;S.tower.equipped=!S.tower.equipped;S.equippedGear.Artifact=S.tower.equipped?'chrono-gear':null;save();renderTower();renderOdds()});document.getElementById('equip-endless-artifact').addEventListener('click',()=>{if(!S.endless.artifacts.length)return;S.endless.equipped=!S.endless.equipped;S.equippedGear.Artifact=S.endless.equipped?S.endless.artifacts[0]:null;save();renderEndless();renderOdds()});document.querySelectorAll('.modal-backdrop').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)m.classList.remove('open')}));
// Auto battle advances one encounter at a time with a cooldown; no background infinite loop or free repeated rewards.
let autoRollTicks=0;setInterval(()=>{if(currentView==='battle'&&!battleBusy&&S.team.length&&!(S.wave>=CAMPAIGN_MAX_WAVE&&S.checkpoint>=CAMPAIGN_MAX_WAVE)){if(!enemy)prepareEnemy();if(enemy&&enemyHp<=0)startNextWave();else if(enemy)fightCampaign();}renderEventTimer();tickGuildBossDecay();if(currentView==='guild')renderGuild();if(currentView==='summon'&&S.autoSummon){autoRollTicks++;const speed=1+gearBonus('rollSpeed');if(autoRollTicks>=Math.max(1,Math.ceil(4/speed))){autoRollTicks=0;if(S.gold>=250){const old=rollCount;rollCount=1;doSummons();rollCount=old}else{S.autoSummon=false;save();render();notify('Auto-summon paused: not enough gold.')}}}},1000);
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(document.getElementById('view-'+v))go(v,false)});
if(!enemy)prepareEnemy();checkUnlocks();render();const initial=location.hash.slice(1);if(initial&&document.getElementById('view-'+initial))go(initial,false);if(!S.tutorialDone&&S.units.length===0)setTimeout(tutorial,350);save();
